const themeButton = document.getElementById("btn-theme");const page = document.body && document.body.dataset ? document.body.dataset.page :null;function setThemeDark(enabled){document.documentElement.classList.toggle("dark",enabled);if (themeButton){const icon = themeButton.querySelector(".material-icons-outlined");if (icon){icon.textContent = enabled ? "light_mode" :"dark_mode";}} try{localStorage.setItem("themeDark",enabled ? "1" :"0");} catch (err){}} if (themeButton){themeButton.addEventListener("click",() =>{setThemeDark(!document.documentElement.classList.contains("dark"));});try{const saved = localStorage.getItem("themeDark");if (saved === "1"){setThemeDark(true);}} catch (err){}} function escapeHtml(value){return String(value ?? "") .replace(/&/g,"&amp;") .replace(/</g,"&lt;") .replace(/>/g,"&gt;") .replace(/"/g,"&quot;") .replace(/'/g,"&#39;");} function setStatus(el,ok,text){if (!el) return;el.className = "result";if (ok === true){el.className += " ok";} else if (ok === false){el.className += " err";} el.textContent = text || "";} async function fetchJson(url,options){const res = await fetch(url,options);const data = await res.json().catch(() => ({}));if (!res.ok){const message = data.detail || data.message || (data.errors ? JSON.stringify(data.errors) :null) || "Request failed";const error = new Error(message);error.status = res.status;error.data = data;throw error;} return data;} async function loadSummary(){const statusEl = document.getElementById("summary-status");setStatus(statusEl,null,"Loading...");try{const data = await fetchJson("/api/admin/summary");document.getElementById("summary-accounts-total").textContent = data.accounts.total ?? "--";document.getElementById("summary-accounts-active").textContent = data.accounts.active ?? "--";document.getElementById("summary-accounts-connected").textContent = data.accounts.connected ?? "--";document.getElementById("summary-accounts-authorized").textContent = data.accounts.authorized ?? "--";document.getElementById("summary-operators-total").textContent = data.operators.total ?? "--";document.getElementById("summary-outbox-queued").textContent = data.outbox.queued ?? "--";document.getElementById("summary-outbox-failed").textContent = data.outbox.failed ?? "--";document.getElementById("summary-outbox-dead").textContent = data.outbox.dead ?? "--";document.getElementById("summary-outbox-processing").textContent = data.outbox.processing ?? "--";document.getElementById("summary-outbox-sent").textContent = data.outbox.sent ?? "--";const lastEventEl = document.getElementById("summary-last-event");const lastEventTimeEl = document.getElementById("summary-last-event-time");if (data.last_event){lastEventEl.textContent = data.last_event.message || "--";lastEventTimeEl.textContent = data.last_event.created_at || "--";} else{lastEventEl.textContent = "--";lastEventTimeEl.textContent = "--";} setStatus(statusEl,true,"Updated");} catch (err){setStatus(statusEl,false,err.message || "Failed");}} function buildAccountRow(account,onSave){const row = document.createElement("tr");row.className = "border-b border-border-light dark:border-border-dark";const accountCell = document.createElement("td");accountCell.className = "py-3 px-3";accountCell.innerHTML = ` <div class="font-semibold">${escapeHtml(account.label || account.phone_number)}</div> <div class="text-xs text-gray-500">ID ${escapeHtml(account.account_id)}</div> <div class="text-xs text-gray-500">${escapeHtml(account.phone_number || "")}</div> `;row.appendChild(accountCell);const labelCell = document.createElement("td");labelCell.className = "py-3 px-3";const labelInput = document.createElement("input");labelInput.className = "w-full bg-gray-100 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg px-2 py-1 text-xs";labelInput.value = account.label || "";labelCell.appendChild(labelInput);row.appendChild(labelCell);const activeCell = document.createElement("td");activeCell.className = "py-3 px-3";const activeInput = document.createElement("input");activeInput.type = "checkbox";activeInput.className = "h-4 w-4";activeInput.checked = Boolean(account.is_active);activeCell.appendChild(activeInput);row.appendChild(activeCell);const statusCell = document.createElement("td");statusCell.className = "py-3 px-3 text-xs text-gray-500 dark:text-gray-400";statusCell.innerHTML = ` <div>Connected:${account.connected ? "yes" :"no"}</div> <div>Authorized:${account.authorized ? "yes" :"no"}</div> `;row.appendChild(statusCell);const userCell = document.createElement("td");userCell.className = "py-3 px-3 text-xs text-gray-500 dark:text-gray-400";const user = account.user ||{};userCell.textContent = user.username || user.phone || user.id || "--";row.appendChild(userCell);const sessionCell = document.createElement("td");sessionCell.className = "py-3 px-3 text-xs text-gray-500 dark:text-gray-400";const session = account.session ||{};sessionCell.innerHTML = ` <div>${escapeHtml(session.name || "")}</div> <div>${escapeHtml(session.path || "")}</div> `;row.appendChild(sessionCell);const actionCell = document.createElement("td");actionCell.className = "py-3 px-3";const saveButton = document.createElement("button");saveButton.className = "btn primary";saveButton.textContent = "Save";const rowStatus = document.createElement("div");rowStatus.className = "result";actionCell.appendChild(saveButton);actionCell.appendChild(rowStatus);row.appendChild(actionCell);saveButton.addEventListener("click",async () =>{rowStatus.className = "result";rowStatus.textContent = "Saving...";try{await onSave({account_id:account.account_id,label:labelInput.value.trim(),is_active:activeInput.checked,rowStatus,});} catch (err){rowStatus.className = "result err";rowStatus.textContent = err.message || "Save failed";}});return row;} async function loadAccounts(){const statusEl = document.getElementById("accounts-status");const tableBody = document.getElementById("accounts-table-body");const emptyState = document.getElementById("accounts-empty");setStatus(statusEl,null,"Loading...");try{const data = await fetchJson("/api/admin/accounts");const accounts = data.accounts || [];tableBody.innerHTML = "";if (accounts.length === 0){emptyState.style.display = "block";setStatus(statusEl,true,"No accounts");return;} emptyState.style.display = "none";accounts.forEach(account =>{const row = buildAccountRow(account,async ({account_id,label,is_active,rowStatus}) =>{const res = await fetchJson(`/api/admin/accounts/${account_id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({label,is_active})});rowStatus.className = "result ok";rowStatus.textContent = res.account && res.account.is_active ? "Saved" :"Saved (inactive)";loadAccounts();});tableBody.appendChild(row);});setStatus(statusEl,true,"Updated");} catch (err){setStatus(statusEl,false,err.message || "Failed");}} function parseSettingValue(input,type){if (type === "bool"){if (input.value === "") return null;return input.value === "true";} if (type === "int"){if (input.value === "") return null;const value = Number(input.value);if (!Number.isFinite(value)) throw new Error("Invalid number");return Math.floor(value);} const text = String(input.value || "").trim();return text === "" ? null :text;} function buildSettingRow(setting,onSave,onReset){const row = document.createElement("tr");row.className = "border-b border-border-light dark:border-border-dark";const keyCell = document.createElement("td");keyCell.className = "py-3 px-3 font-semibold";keyCell.textContent = setting.key;row.appendChild(keyCell);const descCell = document.createElement("td");descCell.className = "py-3 px-3 text-xs text-gray-500 dark:text-gray-400";const restartNote = setting.requires_restart ? " (restart)" :"";descCell.textContent = `${setting.description}${restartNote}`;row.appendChild(descCell);const defaultCell = document.createElement("td");defaultCell.className = "py-3 px-3 text-xs text-gray-500 dark:text-gray-400";defaultCell.textContent = setting.default_value ?? "--";row.appendChild(defaultCell);const currentCell = document.createElement("td");currentCell.className = "py-3 px-3 text-xs text-gray-500 dark:text-gray-400";currentCell.textContent = setting.current_value ?? "--";row.appendChild(currentCell);const inputCell = document.createElement("td");inputCell.className = "py-3 px-3";let input;if (setting.type === "bool"){input = document.createElement("select");input.className = "w-full bg-gray-100 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg px-2 py-1 text-xs";const optionDefault = document.createElement("option");optionDefault.value = "";optionDefault.textContent = "default";input.appendChild(optionDefault);const optionTrue = document.createElement("option");optionTrue.value = "true";optionTrue.textContent = "true";input.appendChild(optionTrue);const optionFalse = document.createElement("option");optionFalse.value = "false";optionFalse.textContent = "false";input.appendChild(optionFalse);if (setting.override_value === true){input.value = "true";} else if (setting.override_value === false){input.value = "false";} else{input.value = "";}} else{input = document.createElement("input");input.type = setting.type === "int" ? "number" :"text";input.className = "w-full bg-gray-100 dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg px-2 py-1 text-xs";if (setting.override_value !== null && setting.override_value !== undefined){input.value = setting.override_value;} else{input.value = "";input.placeholder = setting.current_value ?? "";}} inputCell.appendChild(input);row.appendChild(inputCell);const actionCell = document.createElement("td");actionCell.className = "py-3 px-3";const saveButton = document.createElement("button");saveButton.className = "btn primary";saveButton.textContent = "Save";const resetButton = document.createElement("button");resetButton.className = "btn";resetButton.textContent = "Reset";const rowStatus = document.createElement("div");rowStatus.className = "result";actionCell.appendChild(saveButton);actionCell.appendChild(resetButton);actionCell.appendChild(rowStatus);row.appendChild(actionCell);saveButton.addEventListener("click",async () =>{rowStatus.className = "result";rowStatus.textContent = "Saving...";try{const value = parseSettingValue(input,setting.type);await onSave(setting.key,value);rowStatus.className = "result ok";rowStatus.textContent = "Saved";} catch (err){rowStatus.className = "result err";rowStatus.textContent = err.message || "Save failed";}});resetButton.addEventListener("click",async () =>{rowStatus.className = "result";rowStatus.textContent = "Resetting...";try{await onReset(setting.key);rowStatus.className = "result ok";rowStatus.textContent = "Reset";} catch (err){rowStatus.className = "result err";rowStatus.textContent = err.message || "Reset failed";}});return row;} async function loadSettings(){const statusEl = document.getElementById("settings-status");const tableBody = document.getElementById("settings-table-body");const emptyState = document.getElementById("settings-empty");setStatus(statusEl,null,"Loading...");try{const data = await fetchJson("/api/admin/settings");const settingsList = data.settings || [];tableBody.innerHTML = "";if (settingsList.length === 0){emptyState.style.display = "block";setStatus(statusEl,true,"No settings");return;} emptyState.style.display = "none";async function patchSettings(values){const response = await fetchJson("/api/admin/settings",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({values})});if (response.requires_restart){setStatus( statusEl,true,"Updated. Restart required:" + response.restart_keys.join(",") );} else{setStatus(statusEl,true,"Updated");} await loadSettings();} settingsList.forEach(setting =>{const row = buildSettingRow( setting,async (key,value) => patchSettings({[key]:value}),async (key) => patchSettings({[key]:null}) );tableBody.appendChild(row);});setStatus(statusEl,true,"Updated");} catch (err){setStatus(statusEl,false,err.message || "Failed");}} const refreshButton = document.getElementById("btn-refresh");if (refreshButton){refreshButton.addEventListener("click",() =>{if (page === "dashboard") loadSummary();if (page === "accounts") loadAccounts();if (page === "settings") loadSettings();});} if (page === "dashboard"){loadSummary();} if (page === "accounts"){loadAccounts();} if (page === "settings"){loadSettings();}
